import{_ as n,l as i,o as e,c as E,v as o,p as B,x as t,d as l,i as s,S as p}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"太大而不能倒","description":"","frontmatter":{"title":"太大而不能倒","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/too-big-to-fail.md","filePath":"econ/too-big-to-fail.md","lastUpdated":1789023840000}'),d={name:"econ/too-big-to-fail.md"};function A(h,a,T,c,m,F){const r=i("Mermaid");return e(),E("div",null,[a[1]||(a[1]=o('<h1 id="太大而不能倒" tabindex="-1">太大而不能倒 <a class="header-anchor" href="#太大而不能倒" aria-label="Permalink to &quot;太大而不能倒&quot;">​</a></h1><div class="epigraph"><p>若市场相信某家机构倒闭的社会成本不可接受，对该机构负债的担保就不必写在任何保单上。</p><footer>—— 据 Stern and Feldman, Too Big to Fail: The Hazards of Bank Bailouts, Brookings Institution Press, 2004 整理</footer></div><p>定位：<a href="/econ/lender-of-last-resort">上一课</a>。Bagehot 已经把窗口限制在好抵押与惩罚利率上，并把偿付能力问题交给处置。本课缺口是系统性机构的<strong>隐担保</strong>：规模、关联、不可替代的功能使市场相信股东与无保险债权人也会被保住。不重列三句规则，不把隐担保写成存款保险。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>最后贷款人删的是流动性坏均衡，筛选靠抵押。若机构大到处置会中断支付、冻结银行间网络、或触发上一课尚未写尽的传染，事后最优往往是连资不抵债也救。事前，债权人把这一事后最优写进价格：资金成本下降，杠杆与风险上升。Stern 与 Feldman 把这种信念称为太大而不能倒（TBTF）。</p><p>缺口不是「危机里要不要救」，而是：隐担保如何改变平时的资本结构，以及它与 Bagehot 的哪一句冲突。冲突点明确——好抵押要求资不抵债走处置；TBTF 说处置不可信。</p><p><span class="marginnote">TBTF 不是资产负债表的一个科目。它是均衡信念：无保险负债的信用利差里已经扣除了预期救助。利差变窄是证据的候选，不是定义本身。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把担保分成三层，已经出场的两层不再展开。零售<a href="/econ/deposit-insurance">存款保险</a>是显式、有上限的保单。Bagehot 窗口是显式、有抵押的流动性。TBTF 是对<strong>未保险、无抵押、甚至股权</strong>的预期转移支付。它不出现在费率表里，出现在债权人愿意接受的更薄利差、以及经理更愿意保留的尾部风险。</p><p>对照 Bagehot。自由放贷针对好抵押上的流动性；惩罚利率阻止把窗口当日常资本；好抵押把资不抵债剔出窗口。TBTF 反过来：数量上可能无上限，价格上可能接近市场而非惩罚，抵押上可能接受已经减值的资产——因为「不救」的社会成本被写成不可接受。时间不一致在<a href="/econ/time-inconsistency">承诺</a>课已经有一般形式；这里的具体对象是处置的不可信。</p>',10)),(e(),B(p,null,{default:t(()=>[s(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20SYS%5B%22%E8%A7%84%E6%A8%A1%E6%88%96%E4%B8%8D%E5%8F%AF%E6%9B%BF%E4%BB%A3%E5%8A%9F%E8%83%BD%22%5D%20--%3E%20BELIEF%5B%22%E5%B8%82%E5%9C%BA%3A%20%E5%A4%84%E7%BD%AE%E4%B8%8D%E5%8F%AF%E4%BF%A1%22%5D%0A%20%20BELIEF%20--%3E%20SPREAD%5B%22%E6%97%A0%E4%BF%9D%E9%99%A9%E8%B4%9F%E5%80%BA%E5%88%A9%E5%B7%AE%E5%8F%98%E7%AA%84%22%5D%0A%20%20SPREAD%20--%3E%20LEV%5B%22%E7%A7%81%E4%BA%BA%E6%9D%A0%E6%9D%86%E4%B8%8A%E5%8D%87%22%5D%0A%20%20BAGEHOT%5B%22Bagehot%3A%20%E5%A5%BD%E6%8A%B5%E6%8A%BC%2C%20%E6%83%A9%E7%BD%9A%E5%88%A9%E7%8E%87%22%5D%20--%3E%20RESOLVE%5B%22%E8%B5%84%E4%B8%8D%E6%8A%B5%E5%80%BA%E8%B5%B0%E5%A4%84%E7%BD%AE%22%5D%0A%20%20BELIEF%20--%3E%20CONFLICT%5B%22%E4%B8%8E%E5%A4%84%E7%BD%AE%E6%89%BF%E8%AF%BA%E5%86%B2%E7%AA%81%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>政策含义先停在机制：要恢复 Bagehot，必须使处置可置信——损失能落在无保险债权和股权上，功能能继续。具体的遗嘱、自救债工具是监管后文，本课不列条款。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是社会成本与私人成本的缺口被债权人提前资本化。倒闭的外部性——支付中断、<a href="/econ/bank-contagion">传染</a>、火售——进入事后救助的目标函数，不进入该机构股东的目标函数。债权人若分享事后救助，事前就按准政府信用放贷。于是 TBTF 机构的私人 \\(D^\\ast\\) 更高，与后课权衡里「银行私人杠杆偏高」是同一外部性，只是这里的通道是<strong>资金价格</strong>，不是税盾。</p><p>与保险的差别：保险覆盖集是公开的，看跌的标的是被保险存款；TBTF 的覆盖集是博弈结果，标的可以包括批发债甚至股权。Keeley 的特许权价值在这里被另一块租金替换：太小的机构没有这块隐租金，竞争条件不对称。</p><h3 id="救助窗口不是最后贷款人" tabindex="-1">救助窗口不是最后贷款人 <a class="header-anchor" href="#救助窗口不是最后贷款人" aria-label="Permalink to &quot;救助窗口不是最后贷款人&quot;">​</a></h3><p>把股权价值保全写成「流动性支持」，直接破坏 Bagehot 第三句。本课要能把两句话分开：对有偿付能力机构按折扣放贷，是 LOLR；对资不抵债机构的注资或债务担保，是财政或有。混用使惩罚利率失去筛选，使「太大」成为最便宜的融资策略。</p><p><span class="marginnote">跨境机构使「谁的最后贷款人」与「谁的纳税人」错位。本币窗口救不了外币批发债，隐担保若以外币计，还要回到储备与互换，不能用一句 TBTF 跨币种使用。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把所有危机救助都贴上 TBTF：针对市场功能的证券购买、针对支付系统的流动性，可以不保全某家股东。也不要把「系统重要性」清单当成已经解决信念——清单本身可能强化隐担保，除非配上可置信的损失吸收。</p><p>本课不写巴塞尔公式。下一课才把亏损顺序写成可审计比率；资本是对 TBTF 激励的数量阀，不是对 Bagehot 三句的改写。</p><p>后课默认：TBTF 是处置不可信时的隐担保，降低无保险负债成本，与 Bagehot 的好抵押冲突。流动性窗口不是保全股权。资本监管下一课才出场。</p><p>规模通过外部性进入事后目标，通过利差进入事前杠杆。两者必须分开写，才能对着干。</p><p>隐担保的覆盖集是均衡，不是保单。不要把它写成存款保险的一个档位。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Bagehot 要求资不抵债走处置；TBTF 是处置不可信时的隐担保。</li><li>信念被写进无保险负债的价格，私人杠杆系统性偏高。</li><li>保全股权的「流动性支持」不是最后贷款人。</li><li>出处：Stern and Feldman, <em>Too Big to Fail</em>, 2004；对照 Bagehot, <em>Lombard Street</em>。</li></ul>',15))])}const f=n(d,[["render",A]]);export{g as __pageData,f as default};
